<main id="main" class="section-page"><header class="page-heading"><p class="eyebrow"><a href="<?php echo esc_url(tp48_page_url('the-journal')); ?>">The Journal</a></p><h1><?php the_archive_title(); ?></h1><?php the_archive_description('<div class="archive-description">','</div>'); ?></header><section class="section-space ruled"><nav class="category-nav" aria-label="Danh mục"><a href="<?php echo esc_url(tp48_page_url('the-journal')); ?>">Tất cả</a><?php foreach (get_categories(['hide_empty'=>true]) as $category): ?><a href="<?php echo esc_url(get_category_link($category)); ?>"<?php if (is_category($category->term_id)) echo ' aria-current="page"'; ?>><?php echo esc_html($category->name); ?></a><?php endforeach; ?></nav><?php if (have_posts()): ?><div class="story-grid"><?php while (have_posts()): the_post(); get_template_part('template-parts/story-card'); endwhile; ?></div><div class="pagination"><?php the_posts_pagination(); ?></div><?php else: tp48_placeholder('Chưa có bài viết trong danh mục này.'); endif; ?></section></main><?php get_footer(); ?>
